BEGIN;
CREATE TEMP TABLE s2g(ts text[],rs text[],pm boolean) ON COMMIT DROP;
INSERT INTO s2g VALUES
(ARRAY['panel_batches','panel_handovers','module_schedule','stage_wastage','installation_checklist','production_task_templates','project_subtasks','project_task_schedule_uploads','task_benchmarks','material_alerts','site_receipt_checklist','kickoff_meetings','project_backfills','project_scope_exclusions'],ARRAY['planning_head','planning_engineer','head_of_projects','production_head','head_operations','senior_factory_supervisor','factory_floor_supervisor','fabrication_foreman','site_engineer','site_installation_mgr'],true),
(ARRAY['site_readiness'],ARRAY['planning_head','planning_engineer','head_of_projects','production_head','head_operations','senior_factory_supervisor','factory_floor_supervisor','fabrication_foreman','site_engineer','site_installation_mgr','delivery_rm_lead'],true),
(ARRAY['dispatch_log','dispatch_material_log','dispatch_signoffs'],ARRAY['logistics_manager','stores_executive','production_head','head_of_projects','planning_head','delivery_rm_lead','site_installation_mgr'],false),
(ARRAY['project_material_plans','project_material_plan_items'],ARRAY['planning_head','planning_engineer','head_of_projects','production_head','costing_engineer','quantity_surveyor','procurement_assistant','purchase_assistant','stores_executive','finance_manager'],false),
(ARRAY['inventory_items','stores_inventory'],ARRAY['stores_executive','production_head','head_of_projects','planning_head','procurement_assistant','purchase_assistant','senior_factory_supervisor','finance_manager'],false),
(ARRAY['payment_approvals','depreciation_block_reference'],ARRAY['finance_manager','accounts_executive'],false),
(ARRAY['sales_stage_history'],ARRAY['sales_executive','sales_associate','delivery_rm_lead'],false),
(ARRAY['design_stage_history'],ARRAY['head_operations','principal_architect','senior_architect','project_architect','structural_architect','planning_head'],false),
(ARRAY['red_flag_alerts','weekly_report_configs'],ARRAY['head_of_projects','planning_head','production_head','finance_manager'],false),
(ARRAY['construction_journal','client_milestone_photos'],ARRAY['head_of_projects','planning_head','sales_executive','sales_associate'],true);
CREATE TEMP TABLE s2t AS SELECT t.tbl,g.rs,g.pm,replace(p.policyname,'_scoped','') pname,p.roles pr FROM s2g g CROSS JOIN LATERAL unnest(ts) t(tbl) LEFT JOIN pg_policies p ON p.schemaname='public' AND p.tablename=t.tbl AND p.cmd='SELECT' AND p.policyname LIKE '%_scoped';
DO $reset$ DECLARE t record;BEGIN FOR t IN SELECT * FROM s2t LOOP EXECUTE format('ALTER POLICY %I ON public.%I USING (true)',t.pname||'_scoped',t.tbl);EXECUTE format('ALTER POLICY %I ON public.%I RENAME TO %I',t.pname||'_scoped',t.tbl,t.pname);END LOOP;END $reset$;
CREATE TEMP TABLE s2s(role text PRIMARY KEY,uid uuid,syn boolean) ON COMMIT DROP;
INSERT INTO s2s SELECT role,COALESCE((SELECT auth_user_id FROM public.profiles p WHERE p.role::text=k.role AND is_active AND auth_user_id IS NOT NULL ORDER BY id LIMIT 1),gen_random_uuid()),NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.role::text=k.role AND is_active AND auth_user_id IS NOT NULL) FROM (SELECT DISTINCT unnest(rs) role FROM s2g UNION SELECT unnest(ARRAY['super_admin','managing_director','finance_director','sales_director','architecture_director','hr_executive'])) k;
GRANT SELECT ON s2s,s2t TO authenticated;
CREATE TEMP TABLE s2c(role text,tbl text,syn boolean,b bigint,a bigint) ON COMMIT DROP;
CREATE TEMP TABLE s2h AS SELECT pg_get_functiondef(p.oid) def FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('has_role','get_user_role','user_has_any_role');
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $f$ SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_temp.s2s s WHERE s.uid=_user_id AND syn) THEN EXISTS(SELECT 1 FROM pg_temp.s2s s WHERE s.uid=_user_id AND role=_role::text) ELSE EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_user_id AND role=_role AND is_active) END $f$;
CREATE OR REPLACE FUNCTION public.get_user_role(_user_id uuid) RETURNS public.app_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $f$ SELECT COALESCE((SELECT role::public.app_role FROM pg_temp.s2s s WHERE s.uid=_user_id AND syn),(SELECT role FROM public.profiles WHERE auth_user_id=_user_id AND is_active LIMIT 1)) $f$;
CREATE OR REPLACE FUNCTION public.user_has_any_role(_user_id uuid,_roles public.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $f$ SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_temp.s2s s WHERE s.uid=_user_id AND syn) THEN EXISTS(SELECT 1 FROM pg_temp.s2s s WHERE s.uid=_user_id AND role=ANY(_roles::text[])) ELSE EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_user_id AND role=ANY(_roles) AND is_active) END $f$;
DO $b$ DECLARE s record;t record;c bigint;BEGIN FOR s IN SELECT * FROM s2s LOOP PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.uid,'role','authenticated')::text,true);FOR t IN SELECT * FROM s2t LOOP EXECUTE 'SET LOCAL ROLE authenticated';EXECUTE format('SELECT count(*) FROM public.%I',t.tbl) INTO c;EXECUTE 'RESET ROLE';INSERT INTO s2c VALUES(s.role,t.tbl,s.syn,c,NULL);END LOOP;END LOOP;END $b$;
DO $scope$ DECLARE t record;p record;roles_sql text;def text;pred text;BEGIN FOR t IN SELECT * FROM s2t LOOP SELECT * INTO p FROM pg_policies WHERE schemaname='public' AND tablename=t.tbl AND policyname=t.pname;
IF NOT FOUND OR p.qual<>'true' OR p.cmd<>'SELECT' OR p.roles<>t.pr OR p.permissive<>'PERMISSIVE' THEN RAISE EXCEPTION 'Anchor changed';END IF;
IF EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename=t.tbl AND policyname=t.pname||'_scoped') THEN RAISE EXCEPTION 'Name collision';END IF;
SELECT string_agg(quote_ident(x),', ') INTO roles_sql FROM unnest(p.roles) x;
def:=format('DROP POLICY IF EXISTS %I ON public.%I; DROP POLICY IF EXISTS %I ON public.%I; CREATE POLICY %I ON public.%I AS %s FOR SELECT TO %s USING (%s);',t.pname||'_scoped',t.tbl,t.pname,t.tbl,t.pname,t.tbl,p.permissive,roles_sql,p.qual);
-- Backup writes excluded from rolled-back regression.
pred:=format('public.is_tier1_or_super(auth.uid()) OR public.user_has_any_role(auth.uid(),%L::public.app_role[])',t.rs::text);
IF t.pm AND EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t.tbl AND column_name='project_id') THEN pred:=pred||' OR public.user_can_access_project(auth.uid(),project_id)';END IF;
EXECUTE format('ALTER POLICY %I ON public.%I USING (%s)',t.pname,t.tbl,pred);EXECUTE format('ALTER POLICY %I ON public.%I RENAME TO %I',t.pname,t.tbl,t.pname||'_scoped');END LOOP;END $scope$;
DO $after$ DECLARE s record;t record;c bigint;b bigint;ok boolean;BEGIN FOR s IN SELECT * FROM s2s LOOP PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.uid,'role','authenticated')::text,true);FOR t IN SELECT * FROM s2t LOOP EXECUTE 'SET LOCAL ROLE authenticated';EXECUTE format('SELECT count(*) FROM public.%I',t.tbl) INTO c;EXECUTE 'RESET ROLE';SELECT r.b INTO b FROM s2c r WHERE role=s.role AND tbl=t.tbl;UPDATE s2c SET a=c WHERE role=s.role AND tbl=t.tbl;
ok:=s.role=ANY(t.rs) OR s.role=ANY(ARRAY['super_admin','managing_director','finance_director','sales_director','architecture_director']);IF ok AND c<b THEN RAISE EXCEPTION 'Group lost access %, %',s.role,t.tbl;END IF;IF s.role='hr_executive' AND c>b THEN RAISE EXCEPTION 'Control gained';END IF;END LOOP;END LOOP;
RAISE NOTICE 'COUNTS %',(SELECT jsonb_agg(to_jsonb(r) ORDER BY tbl,role) FROM s2c r);
FOR s IN SELECT * FROM s2s WHERE role='delivery_rm_lead' LOOP PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.uid,'role','authenticated')::text,true);FOR t IN SELECT cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename='site_readiness' AND cmd IN ('INSERT','UPDATE') LOOP EXECUTE 'SET LOCAL ROLE authenticated';EXECUTE 'SELECT CASE WHEN ('||coalesce(t.with_check,t.qual)||') THEN 1 ELSE 0 END' INTO c;EXECUTE 'RESET ROLE';IF c<>1 THEN RAISE EXCEPTION 'Readiness regression';END IF;END LOOP;END LOOP;
FOR t IN SELECT def FROM s2h LOOP EXECUTE t.def;END LOOP;PERFORM set_config('request.jwt.claims','{}',true);END $after$;

SELECT jsonb_agg(to_jsonb(r) ORDER BY tbl,role) AS before_after FROM s2c r;
ROLLBACK;
